import {test,expect,type APIRequestContext,type Page} from '@playwright/test';
import {randomUUID} from 'node:crypto';
import {readFile,writeFile} from 'node:fs/promises';
import {api,post,get,login,ctx,origin,screenshot} from './notices';
import type {AiContent,AiAsset,AiInputDetail,AiSourcePicker} from '@/server/ai-input/contracts';
export {api,post,get,login,ctx,origin,screenshot};
export const synthetic='合成テスト：肌を清潔に保ちます。実在の商品ではありません。';
export const content=(text=synthetic):AiContent=>({title:`합성 입력 ${randomUUID().slice(0,6)}`,scope:{classification:'general_cosmetic',language:'ja',media:'pop',use:'매장 POP'},kind:'text',text,sources:[],selectedPages:[],submission:null,products:[]});
export async function create(r:APIRequestContext,c=content(),visibility='context'){return post(r,'/api/ai-input',{contextId:ctx,visibility,content:c,idempotencyKey:randomUUID()}) as Promise<AiInputDetail>;}
export async function detail(r:APIRequestContext,id:string){return get<AiInputDetail>(r,`/api/ai-input/${id}`);}
export async function extract(r:APIRequestContext,d:AiInputDetail){return post(r,`/api/ai-input/${d.id}/extract`,{versionId:d.version.id,expectedRunId:d.runs[0]?.id??null,idempotencyKey:randomUUID()}) as Promise<{runId:string;detail:AiInputDetail}>;}
export async function upload(r:APIRequestContext,name:string){const csrf=await(await r.get('/api/auth/csrf')).json();const response=await r.post(`/api/ai-input/assets?contextId=${ctx}&visibility=context`,{headers:{Origin:origin(),'X-CSRF-Token':csrf.csrfToken},multipart:{file:{name,mimeType:name.endsWith('.pdf')?'application/pdf':'image/png',buffer:await readFile(`tests/fixtures/ai-input/${name}`)},idempotencyKey:randomUUID()}});expect(response.status(),await response.text()).toBe(200);return response.json() as Promise<AiAsset>;}
export async function open(page:Page,id:string){await page.goto(`/ai-input/${id}?context=${ctx}`);await expect(page.getByRole('region',{name:'저장된 입력',exact:true})).toBeVisible();}
export async function newInput(page:Page,title:string,kind='text'){await page.goto(`/ai-input/new?context=${ctx}`);await expect(page.getByRole('textbox',{name:'입력 제목',exact:true})).toBeVisible();await page.getByRole('textbox',{name:'입력 제목',exact:true}).fill(title);await page.getByRole('combobox',{name:'제품 분류',exact:true}).selectOption('general_cosmetic');await page.getByRole('textbox',{name:'사용처',exact:true}).fill('합성 매장 POP');await page.getByRole('combobox',{name:'입력 형식',exact:true}).selectOption(kind);}
export async function save(page:Page){await page.getByRole('button',{name:'입력 저장',exact:true}).click();await expect(page).toHaveURL(/\/ai-input\/[A-Za-z0-9_-]+\?/);await expect(page.getByRole('region',{name:'저장된 입력',exact:true})).toBeVisible();return /\/ai-input\/([^?]+)/.exec(page.url())![1];}
export async function read(page:Page){await page.getByRole('button',{name:'저장한 입력 읽기',exact:true}).click();await expect(page.getByRole('status').filter({hasText:'읽기 상태를 확인했습니다.'})).toBeVisible({timeout:45000});}
export async function chooseUpload(page:Page,name:string){await page.getByLabel('새 원본 파일',{exact:true}).setInputFiles(`tests/fixtures/ai-input/${name}`);await expect(page.getByRole('status').filter({hasText:'파일을 업로드했습니다.'})).toBeVisible();const source=page.getByRole('group',{name:'실제로 읽을 자료 선택',exact:true});await source.getByRole(name.endsWith('.pdf')?'radio':'checkbox',{name:new RegExp(name.replace('.','\\.'))}).check();}
export async function suspend(admin:APIRequestContext,status:'active'|'suspended'){const data=await get<{members:{id:string;revision:number;data:{userId:string}}[]}>(admin,`/api/contexts/${ctx}/members`);const member=data.members.find(m=>m.data.userId==='user-luna')!;const csrf=await(await admin.get('/api/auth/csrf')).json();const r=await admin.patch(`/api/contexts/${ctx}/members/${member.id}`,{headers:{Origin:origin(),'X-CSRF-Token':csrf.csrfToken},data:{expectedRevision:member.revision,status}});expect(r.status(),await r.text()).toBe(200);}
export function tracing(){test.use({actionTimeout:15000});test.beforeEach(async({page})=>{await page.context().tracing.start({screenshots:true,snapshots:true,sources:true});});test.afterEach(async({page},info)=>{await writeFile(info.outputPath('final-dom-private.html'),await page.content());await page.screenshot({path:info.outputPath(info.status===info.expectedStatus?'final-private.png':'failure-private.png'),fullPage:true});await page.context().tracing.stop({path:info.outputPath('journey-private-trace.zip')});});}
export async function picker(r:APIRequestContext){return get<AiSourcePicker>(r,`/api/ai-input/sources?contextId=${ctx}`);}
